    local humanoidRootPart = game.Players.LocalPlayer.Character.HumanoidRootPart
    humanoidRootPart.CFrame = humanoidRootPart.CFrame + Vector3.new(0, 50, 0)
    task.wait(0.5)
end
function TelePPlayer(cframe2)
    game.Players.LocalPlayer.Character.HumanoidRootPart.CFrame = cframe2
end
function topos(cframe2)
    local player, cframe3
    player = game
    player = player.Players
    player = player.LocalPlayer
    if player.Character then
        if 0 < player.Character.Humanoid.Health then
            if player.Character:FindFirstChild("HumanoidRootPart") then
                local distance = (cframe2.Position - player.Character.HumanoidRootPart.Position).Magnitude
                if not cframe2 then
                    return
                end
                local nearestTeleporter = CheckNearestTeleporter(cframe2)
                if nearestTeleporter then
                    local requestEntrance2 = requestEntrance
                    cframe3 = nearestTeleporter
                    requestEntrance2(cframe3)
                end
                local character = player.Character
                cframe3 = character
                if not character.FindFirstChild(cframe3, "PartTele") then
                    cframe3 = "Part"
                    local v = Instance.new(cframe3, player.Character)
                    cframe3 = Vector3
                    cframe3 = cframe3.new
                    cframe3 = cframe3(10, 1, 10)
                    v.Size = cframe3
                    v.Name = "PartTele"
                    v.Anchored = true
                    v.Transparency = 1
                    v.CanCollide = true
                    cframe3 = WaitHRP
                    cframe3 = cframe3(player)
                    cframe3 = cframe3.CFrame
                    v.CFrame = cframe3
                    cframe3 = v
                    cframe3:GetPropertyChangedSignal("CFrame"):Connect(function()
                        if not num3 then
                            return
                        end
                        task.wait()
                        if player.Character then
                            if player.Character:FindFirstChild("HumanoidRootPart") then
                                local hrp = WaitHRP(player)
                                hrp.CFrame = cframe3.CFrame
                            end
                        end
                    end)
                end
                num3 = true
                local v2 = game
                cframe3 = v2
                local service = v2.GetService(cframe3, "TweenService")
                cframe3 = service
                local track = service.Create(cframe3, player.Character.PartTele, TweenInfo.new(distance / 360, Enum.EasingStyle.Linear), {CFrame = cframe2})
                cframe3 = track.Play
                cframe3(track)
                cframe3 = track.Completed
                local v8 = cframe3
                cframe3 = cframe3.Connect
                cframe3(v8, function(arg)
                    if arg == Enum.PlaybackState.Completed then
                        if player.Character:FindFirstChild("PartTele") then
                            player.Character.PartTele:Destroy()
                        end
                        num3 = false
                    end
                end)
            end
        end
    end
end
function stopTeleport()
    num3 = false
    local localPlayer2 = game.Players.LocalPlayer
    if localPlayer2.Character:FindFirstChild("PartTele") then
        localPlayer2.Character.PartTele:Destroy()
    end
end
spawn(function()
    while true do
        if not task.wait() then
            break
        end
        if not num3 then
            stopTeleport()
        end
    end
end)
