function TP13(cframe2)
    local player
    local position2 = cframe2.Position
    player = game
    player = player.Players
    player = player.LocalPlayer
    player = player.Character
    player = player.HumanoidRootPart
    player = player.Position
    local distance = (position2 - player).Magnitude
    player = game
    local v = player
    player = player.GetService
    player = player(v, "TweenService")
    local v2 = player
    player = player.Create
    player = player(v2, game:GetService("Players").LocalPlayer.Character.HumanoidRootPart, TweenInfo.new(distance / TweenSpeed, Enum.EasingStyle.Linear), {CFrame = cframe2})
    local v8 = player
    player = player.Play
    player = player(v8)
    characterAdded.Stop = function(arg)
        player:Cancel()
    end
    return characterAdded
end
function fastpos(cframe2)
