function TweenToPosition(cframe2)
    local character = game.Players.LocalPlayer.Character
    local cframe3 = character or v
    if character then
        cframe3 = character:FindFirstChild("HumanoidRootPart")
    end
    if not cframe3 then
        return
    end
    local tween2 = game:GetService("TweenService"):Create(cframe3, TweenInfo.new((cframe3.Position - cframe2.Position).Magnitude / 300, Enum.EasingStyle.Linear), {CFrame = cframe2})
    tween2:Play()
    tween2.Completed:Wait()
end
function Skill(arg)
    local VirtualInputManager = game:GetService("VirtualInputManager")
    VirtualInputManager:SendKeyEvent(true, Enum.KeyCode[arg], false, game)
    task.wait(0.05)
    VirtualInputManager:SendKeyEvent(false, Enum.KeyCode[arg], false, game)
end
function Click()
    local VirtualInputManager = game:GetService("VirtualInputManager")
    VirtualInputManager:SendMouseButtonEvent(0, 0, 0, true, game, 1)
    task.wait(0.05)
    VirtualInputManager:SendMouseButtonEvent(0, 0, 0, false, game, 1)
end
function FindWeapon(arg)
    local backpack = game.Players.LocalPlayer.Backpack
    for _, item in ipairs(backpack:GetChildren()) do
        if item:IsA("Tool") then
            local kind = item.ToolTip
            if (arg == "Melee" and (kind == "Melee" or item.Name == "Combat"))
                or (arg == "Sword" and kind == "Sword")
                or (arg == "Gun" and kind == "Gun")
                or (arg == "Fruit" and kind == "Blox Fruit") then
                return item.Name
            end
        end
    end
    return nil
end
function EquipWeapon(name)
    if not name then
        return
    end
    local localPlayer2 = game.Players.LocalPlayer
    local child = localPlayer2:WaitForChild("Backpack"):FindFirstChild(name)
    if child then
        localPlayer2.Character.Humanoid:EquipTool(child)
    end
end
function AttackAllSkills()
    local weapon = FindWeapon("Melee")
    local weapon2 = FindWeapon("Sword")
    local weapon3 = FindWeapon("Fruit")
    local weapon4 = FindWeapon("Gun")
    if weapon then
        EquipWeapon(weapon)
        Skill("Z")
        Skill("X")
        Skill("C")
        Skill("V")
        Click()
    end
    if weapon2 then
        EquipWeapon(weapon2)
        Skill("Z")
        Skill("X")
        Click()
    end
    if weapon3 then
        EquipWeapon(weapon3)
        Skill("Z")
        Skill("X")
        Skill("C")
        Skill("F")
        Click()
    end
    if weapon4 then
        EquipWeapon(weapon4)
        Skill("Z")
        Skill("X")
        Click()
    end
end
