        for _, location in pairs(workspace._WorldOrigin.Locations:GetChildren()) do
            if location.Name == "Island " .. arg then
                if num12 > (location.Position - game.Players.LocalPlayer.Character.HumanoidRootPart.Position).Magnitude then
                    num12 = (location.Position - game.Players.LocalPlayer.Character.HumanoidRootPart.Position).Magnitude
                end
            end
        end
        for _, location in pairs(workspace._WorldOrigin.Locations:GetChildren()) do
            if location.Name == "Island " .. arg then
                if num12 >= (location.Position - game.Players.LocalPlayer.Character.HumanoidRootPart.Position).Magnitude then
                    return location
