__UI.tab12.AddButton(str37, {
    Title = "FPS Boost",
    Description = "TÄng Fps",
    Callback = function()
        local flag5 = true
        local instance = game
        local workspace2 = instance.Workspace
        local lighting = instance.Lighting
        local terrain = workspace2.Terrain
        settings().Rendering.QualityLevel = "Level01"
        for _, descendant in pairs(instance:GetDescendants()) do
            if not descendant:IsA("Part") then
                if not descendant:IsA("Union") then
                    if not descendant:IsA("CornerWedgePart") then
                        if not descendant:IsA("TrussPart") then
                            local v = descendant:IsA("Decal")
                            do
                                if v or descendant:IsA("Texture") and flag5 then
                                    descendant.Transparency = 1
                                    continue
                                end
                            end
                            local v2 = descendant:IsA("ParticleEmitter")
                            do
                                if v2 or descendant:IsA("Trail") then
                                    descendant.Lifetime = NumberRange.new(0)
                                    continue
                                end
                            end
                            if not descendant:IsA("Explosion") then
                                local v8 = descendant:IsA("Fire")
                                if not v8 then
                                    v8 = descendant:IsA("SpotLight")
                                    if not v8 then
                                        v8 = descendant:IsA("Smoke")
                                    end
                                end
                                if v8 then
                                    descendant.Enabled = false
                                end
                            else
                                descendant.BlastPressure = 1
                                descendant.BlastRadius = 1
                            end
                        end
                    end
                end
            else
                descendant.Material = "Plastic"
                descendant.Reflectance = 0
            end
        end
    end,
})
